// -----------------------------------------------------------------------------
// Packets of an RFXtrx, whole (length byte included).
//
// Most come from the test suite of node-rfxcom (MIT), where the bytes recorded
// from real devices are passed to the packet handlers: the length and type
// bytes are put back in front. The others (marked "shaped") follow the layouts
// of the RFXtrx SDK with plausible values.
// -----------------------------------------------------------------------------

const p = (bytes) => Buffer.from(bytes);

/** Status of a current firmware (21 bytes): 433.92 MHz transceiver, Ext 1094. */
export const STATUS_EXT = p([
  0x14, 0x01, 0x00, 0x01, 0x02, 0x53, 0x5e, 0x08, 0x02, 0x25, 0x00, 0x01, 0x01, 0x1c, 0x03, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00,
]);

/** Status of an old firmware (14 bytes, no "start receiver"). */
export const STATUS_OLD = p([
  0x0d, 0x01, 0x00, 0x01, 0x02, 0x53, 0x30, 0x00, 0x02, 0x21, 0x01, 0x00, 0x00, 0x00,
]);

/** Answer to "start receiver". */
export const COPYRIGHT = p([
  0x14,
  0x01,
  0x07,
  0x02,
  0x07,
  ...Buffer.from('Copyright RFXCOM', 'latin1'),
]);

/** Transmitter answers (shaped): ACK, NAK. */
export const TX_ACK = (seq) => p([0x04, 0x02, 0x01, seq, 0x00]);
export const TX_NAK = (seq) => p([0x04, 0x02, 0x01, seq, 0x02]);

